<?php
if (!defined('ABSPATH')) { exit; }
use Atlas\Core\Auth;
final class Atlas_Booking_Queue {
    private static function t($en,$fa) { return isset($_GET['lang']) && $_GET['lang']==='fa' ? $fa : $en; }
    public static function panel() {
        if (!Auth::agency()) return '';
        wp_enqueue_script('atlas-booking-queue',plugins_url('assets/booking-queue.js',__FILE__),array(),ATLAS_CORE_VERSION.'-'.filemtime(__DIR__.'/assets/booking-queue.js'),true);
        wp_localize_script('atlas-booking-queue','atlasBookingQueue',array('listUrl'=>esc_url_raw(rest_url('agency/v1/booking-queue')),'base'=>esc_url_raw(rest_url('agency/v1/bookings/')),'nonce'=>wp_create_nonce('wp_rest'),'loading'=>self::t('Loading reservations…','در حال دریافت رزروها…'),'empty'=>self::t('No reservations in this state.','رزروی با این وضعیت وجود ندارد.'),'error'=>self::t('The queue could not be loaded.','صف رزرو دریافت نشد.'),'confirm'=>self::t('Confirm service','تأیید خدمت'),'reason'=>self::t('Confirmation reason and fulfillment evidence','دلیل تأیید و شواهد ارائه خدمت'),'reasonRequired'=>self::t('Enter the actual confirmation reason.','دلیل واقعی تأیید را وارد کنید.'),'confirmed'=>self::t('Service confirmed. Payment and ticket issuance remain separate.','خدمت تأیید شد. پرداخت و صدور بلیت وضعیت‌های جداگانه دارند.'),'unsafeAmount'=>self::t('Review the exact amount in finance.','مبلغ دقیق را در بخش مالی بررسی کنید.'),'page'=>self::t('Page','صفحه'),
            'states'=>['paid_pending_confirmation'=>self::t('Awaiting confirmation','در انتظار تأیید'),'exception'=>self::t('Needs review','نیازمند بررسی'),'confirmed'=>self::t('Confirmed','تأییدشده'),'verified'=>self::t('Verified','تأییدشده'),'unverified'=>self::t('Unverified','تأییدنشده'),'not_required'=>self::t('No payment required','بدون نیاز به پرداخت')],
            'headers'=>array(self::t('Reservation','رزرو'),self::t('Booking state','وضعیت رزرو'),self::t('Payment state','وضعیت پرداخت'),self::t('Amount','مبلغ'),self::t('Action','اقدام'))));
        return '<details><summary>'.esc_html(self::t('Booking confirmation queue','صف تأیید رزرو')).'</summary><p>'.esc_html(self::t('Confirm only after actual service availability and fulfillment are checked. Payment alone is not confirmation.','فقط پس از بررسی واقعی امکان ارائه خدمت تأیید کنید. پرداخت به‌تنهایی تأیید رزرو نیست.')).'</p><section data-atlas-booking-queue><label>'.esc_html(self::t('Booking state','وضعیت رزرو')).'<select><option value="paid_pending_confirmation">'.esc_html(self::t('Ready for confirmation','آمادهٔ تأیید')).'</option><option value="exception">'.esc_html(self::t('Needs review','نیازمند بررسی')).'</option><option value="confirmed">'.esc_html(self::t('Confirmed','تأییدشده')).'</option></select></label><button type="button" data-refresh>'.esc_html(self::t('Refresh queue','تازه‌سازی صف')).'</button><div data-queue-output tabindex="0" role="region" aria-label="'.esc_attr(self::t('Reservations','رزروها')).'"></div><nav aria-label="'.esc_attr(self::t('Reservation pages','صفحات رزرو')).'"><button type="button" data-prev-page disabled>'.esc_html(self::t('Previous page','صفحه قبل')).'</button><span data-page-status aria-live="polite">'.esc_html(self::t('Page 1','صفحه ۱')).'</span><button type="button" data-next-page disabled>'.esc_html(self::t('Next page','صفحه بعد')).'</button></nav><p role="status" aria-live="polite"></p></section></details>';
    }
}
